                'componentes' => 'V, S, M, FD', 'tempo_execucao' => '10 minutos',
                'alcance' => 'Toque', 'alvo_area_efeito' => 'Criatura morta tocada',
                'duracao' => 'Instantânea', 'teste_resistencia' => 'Nenhum; consulte o texto',
                'resistencia_magia' => 'Sim (inofensiva)', 'versao' => '3.5',
                'descricao' => 'Retorna qualquer morto à vida sem perda de nível, mesmo após séculos.',
                'classes' => ['Clérigo' => 9],
            ],
            [
                'nome' => 'Drenar Energia', 'escola' => 'Necromancia',
                'componentes' => 'V, S', 'tempo_execucao' => '1 ação padrão',
                'alcance' => 'Próximo (7,5 m + 1,5 m/2 níveis)', 'alvo_area_efeito' => 'Um ser vivo',
                'duracao' => 'Instantânea', 'teste_resistencia' => 'Fortitude parcial; consulte o texto',
                'resistencia_magia' => 'Sim', 'versao' => '3.5',
                'descricao' => 'Toque causa 2d4 níveis negativos permanentes.',
                'classes' => ['Clérigo' => 9, 'Mago' => 9, 'Feiticeiro' => 9],
            ],
        ];

        foreach ($magias as $data) {
            $classesData = $data['classes'];
            unset($data['classes']);

            $magia = Magia::updateOrCreate(
                ['nome' => $data['nome'], 'versao' => $data['versao']],
                $data
            );

            $sync = [];
            foreach ($classesData as $nomeClasse => $nivel) {
                if (isset($classesMap[$nomeClasse])) {
                    $sync[$classesMap[$nomeClasse]] = ['nivel' => $nivel];
                }
            }
            $magia->classes()->sync($sync);
        }
    }
}
